<?php
$pageTitle = $pageTitle ?? 'Danh sách hàng hóa'; $activePage = $activePage ?? 'products';
$products = $managementData['products']; $categories = productCategories();
$selectedCategory = $selectedCategory ?? '';
if ($selectedCategory !== '') $products = array_values(array_filter($products, static fn($product) => $product['category'] === $selectedCategory));
$activeNavTarget = 'index.php?page=' . $activePage;
$catalogueDescription = $catalogueDescription ?? 'Tra cứu danh mục, số lượng nhập xuất và tồn kho của từng hàng hóa.';
$catalogueColumns = $catalogueColumns ?? ['category' => 'Nhóm hàng', 'unit' => 'Đơn vị', 'incoming' => 'Tổng nhập', 'outgoing' => 'Tổng xuất', 'closing' => 'Tồn hiện tại'];
$catalogueValue = static function (array $product, string $field) use ($categories): string {
    if (in_array($field, ['incoming', 'outgoing', 'closing'], true)) return $product[$field] === null && $product['tracking_mode'] === 'quantity' ? 'Thiếu số lượng' : productQuantity($product[$field]);
    if ($field === 'category') return $categories[$product['category']];
    if ($field === 'tracking_mode') return $product['tracking_mode'] === 'quantity' ? 'Theo dõi số lượng' : 'Không theo dõi số lượng';
    if ($field === 'last_received_date') return $product[$field] ? date('d/m/Y', strtotime($product[$field])) : 'Chưa nhập';
    if ($field === 'warehouses') return implode(', ', array_unique(array_column($product['movements'], 'warehouse_name'))) ?: 'Chưa có phiếu';
    if ($field === 'decisions') return implode(', ', array_unique(array_filter(array_column($product['movements'], 'decision_number')))) ?: 'Chưa gắn quyết định';
    return $product[$field] ?: 'Chưa có thông tin';
};
require dirname(__DIR__) . '/layouts/dashboard-start.php';
?>
<section class="page-heading"><div><p class="eyebrow">QUẢN LÝ HÀNG HÓA</p><h1><?= escapeHtml($pageTitle) ?><span>.</span></h1><p><?= escapeHtml($catalogueDescription) ?></p></div><span class="audit-readonly"><?= $icon('box') ?>Tồn từ phiếu đã xác nhận</span></section>
<?php if ($previewOnly ?? false): ?><div class="demo-note"><span class="demo-tag">Bản xem trước</span><span>Danh sách hàng hóa bên dưới là dữ liệu mẫu.</span></div><?php endif; ?>
<p id="product-notice" class="account-notice"<?= empty($managementNotice) ? ' hidden' : ' data-management-flash' ?>><?= escapeHtml($managementNotice ?? '') ?></p>
<?php if ($selectedCategory !== ''): ?><section class="metrics product-page-metrics" aria-label="Tổng quan nhóm hàng"><?php foreach ([['box', 'Mã hàng trong nhóm', count($products), 'purple'], ['warehouse', 'Đang sử dụng', count(array_filter($products, static fn($product) => $product['status'] === 'active')), 'green'], ['file', $activePage === 'fixed-assets' ? 'Có quyết định liên quan' : 'Có tồn trong kho', count(array_filter($products, static fn($product) => $activePage === 'fixed-assets' ? (bool) array_filter(array_column($product['movements'], 'decision_number')) : $product['stock'] === 'stock')), 'orange']] as [$glyph, $label, $value, $tone]): ?><article class="metric"><div class="metric-heading"><span><?= $label ?></span><span class="icon-tile <?= $tone ?>"><?= $icon($glyph) ?></span></div><strong class="metric-value"><?= $value ?></strong><p><?= escapeHtml($pageTitle) ?></p></article><?php endforeach; ?></section><?php endif; ?>
<section class="card" id="products-list" data-category="<?= $selectedCategory ?>" aria-labelledby="products-list-title"><div class="card-heading"><div><h2 id="products-list-title"><?= escapeHtml($pageTitle) ?></h2><p>Số lượng theo đơn vị của từng mã hàng · không tính phiếu nháp và phiếu hủy</p></div><span class="subtle-badge"><?= count($products) ?> mã hàng</span></div>
<div class="table-toolbar account-toolbar"><label class="search-field"><?= $icon('search') ?><input id="product-search" type="search" placeholder="Tìm mã, tên, số phiếu…" aria-label="Tìm hàng hóa"></label><div class="table-filters"><select id="product-warehouse" aria-label="Lọc kho"><option value="">Tất cả kho</option><?php foreach ($managementData['warehouses'] as $id => $name): ?><option value="<?= escapeHtml((string) $id) ?>"><?= escapeHtml($name) ?></option><?php endforeach; ?></select><select id="product-stock" aria-label="Lọc tồn kho"><option value="">Tất cả tồn kho</option><option value="stock">Còn tồn</option><option value="empty">Hết tồn</option><option value="unknown">Thiếu số lượng</option><option value="negative">Tồn âm</option><option value="untracked">Không theo dõi số lượng</option></select><select id="product-status" aria-label="Lọc trạng thái hàng hóa"><option value="">Tất cả trạng thái</option><option value="active">Đang sử dụng</option><option value="inactive">Ngừng sử dụng</option></select></div></div>
<div class="table-scroll" tabindex="0" role="region" aria-label="<?= escapeHtml($pageTitle) ?>"><table class="accounts-table"><thead><tr><th><?= $selectedCategory ? 'Mã / Tên ' . escapeHtml(mb_strtolower($pageTitle)) : 'Mã / Tên hàng hóa' ?></th><?php foreach ($catalogueColumns as $label): ?><th><?= escapeHtml($label) ?></th><?php endforeach; ?><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>
<?php foreach ($products as $product): ?><tr data-product="<?= escapeHtml(json_encode($product, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)) ?>"><td><div class="account-identity"><span class="icon-tile purple"><?= $icon('box') ?></span><div><strong><?= escapeHtml($product['name']) ?></strong><small><?= escapeHtml($product['code']) ?></small></div></div></td><?php foreach ($catalogueColumns as $field => $label): ?><td<?= in_array($field, ['incoming', 'outgoing', 'closing'], true) ? ' class="amount" data-product-quantity="' . $field . '"' : ' class="product-cell-' . $field . '"' ?>><?= escapeHtml($catalogueValue($product, $field)) ?></td><?php endforeach; ?><td><span class="status <?= $product['status'] === 'active' ? 'confirmed' : 'cancelled' ?>"><i></i><?= $product['status'] === 'active' ? 'Đang sử dụng' : 'Ngừng sử dụng' ?></span></td><td><div class="account-actions"><button class="button product-details" type="button">Xem</button><?php if ($access['admin']): ?><button class="button edit-product" type="button">Sửa</button><?php endif; ?></div></td></tr><?php endforeach; ?>
</tbody></table></div><p class="empty-state product-empty" hidden><?= $products ? 'Không có hàng hóa phù hợp với bộ lọc.' : 'Chưa có hàng hóa trong hệ thống.' ?></p><div class="table-footer account-table-footer"><span id="product-count" role="status"></span><nav class="account-pagination" aria-label="Phân trang hàng hóa"><span>10 hàng hóa / trang</span><button class="button" id="product-previous" type="button">Trước</button><span id="product-page" aria-live="polite"></span><button class="button" id="product-next" type="button">Sau</button></nav></div></section>
<dialog id="product-dialog" class="account-dialog" aria-labelledby="product-dialog-title"><form method="dialog"><header class="account-dialog-heading"><div><span class="eyebrow">HÀNG HÓA</span><h2 id="product-dialog-title">Chi tiết hàng hóa</h2><p id="product-detail-name"></p></div><button class="icon-button" type="submit" aria-label="Đóng"><?= $icon('close') ?></button></header><div class="account-dialog-body"><dl class="audit-metadata"><?php foreach (['code' => 'Mã hàng', 'category' => 'Nhóm hàng', 'unit' => 'Đơn vị', 'tracking_mode' => 'Theo dõi số lượng', 'status' => 'Trạng thái'] as $field => $label): ?><div><dt><?= $label ?></dt><dd id="product-detail-<?= $field ?>"></dd></div><?php endforeach; ?></dl><h3>Tồn kho theo từng kho</h3><div class="table-scroll" tabindex="0" role="region" aria-label="Tồn theo kho"><table><thead><tr><th>Kho</th><th>Nhập</th><th>Xuất</th><th>Tồn</th></tr></thead><tbody id="product-stock-rows"></tbody></table></div><p class="empty-state" id="product-stock-empty" hidden>Chưa có phiếu đã xác nhận.</p><section class="account-permissions"><h3>Lịch sử nhập / xuất</h3><p class="form-preview-note">Phiếu nháp và phiếu hủy chỉ để tra cứu, không tính vào tồn.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Lịch sử phiếu, có thể cuộn ngang"><table><thead><tr><th>Ngày / Phiếu</th><th>Kho / Loại</th><th>Số lượng</th><th>Trạng thái</th><th>Quyết định</th></tr></thead><tbody id="product-movement-rows"></tbody></table></div><p class="empty-state" id="product-movement-empty" hidden>Chưa có phiếu liên quan.</p></section></div><footer class="account-dialog-footer"><button class="button button-primary" type="submit">Đóng</button></footer></form></dialog>
<dialog id="product-editor" class="account-dialog" aria-labelledby="product-editor-title"><form id="product-form" method="post" action="index.php?page=<?= $activePage ?>" data-preview="<?= ($previewOnly ?? false) ? 'true' : 'false' ?>"><input type="hidden" name="csrf_token" value="<?= escapeHtml($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id"><input type="hidden" name="version"><header class="account-dialog-heading"><div><span class="eyebrow">DANH MỤC HÀNG HÓA</span><h2 id="product-editor-title">Chỉnh sửa hàng hóa</h2><p>Thông tin danh mục và trạng thái sử dụng.</p></div><button class="icon-button" type="button" data-close-product aria-label="Đóng"><?= $icon('close') ?></button></header><div class="account-dialog-body"><p class="form-error" data-form-error role="alert" hidden></p><div class="account-form-grid"><label>Mã hàng <span>*</span><input name="code" maxlength="64" required></label><label>Tên hàng <span>*</span><input name="name" maxlength="255" required></label><label>Nhóm hàng<select name="category"><?php foreach ($selectedCategory ? [$selectedCategory => $categories[$selectedCategory]] : $categories as $value => $label): ?><option value="<?= $value ?>"><?= $label ?></option><?php endforeach; ?></select></label><label>Đơn vị <span>*</span><input name="unit" maxlength="50" required></label><label>Theo dõi số lượng<select name="tracking_mode"><option value="quantity">Theo dõi số lượng</option><option value="none">Không theo dõi số lượng</option></select></label><label>Trạng thái<select name="status"><option value="active">Đang sử dụng</option><option value="inactive">Ngừng sử dụng</option></select></label></div><p class="form-preview-note" id="product-history-note"></p><p class="form-preview-note">Tồn kho được tính từ phiếu nhập/xuất đã xác nhận. Mọi thay đổi thông tin được lưu vào nhật ký thao tác.</p></div><footer class="account-dialog-footer"><button class="button" type="button" data-close-product>Hủy</button><button class="button button-primary" type="submit">Lưu</button></footer></form></dialog>
